package net.officefloor.hq.app.period;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.FetchType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/** A sheet's period: a name, unique on the sheet without regard to case, and the dates it runs from
 * and to, both inclusive. A claim belongs to the period whose dates contain its due-by. Once closed, its
 * due-total, and each person's due-total for it, are the ones fixed when it was closed, until it is
 * reopened. A soft-closed period is closed and its figures fixed the same way, but claims due by a date in it can
 * still change. */
@Entity
@Table(name = "period")
public class Period {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "name_key", nullable = false)
    private String nameKey;

    @Column(name = "from_date", nullable = false)
    private LocalDate from;

    @Column(name = "to_date", nullable = false)
    private LocalDate to;

    @Column(name = "closed", nullable = false)
    private boolean closed;

    /** Whether the period, while closed, is only soft-closed. */
    @Column(name = "soft", nullable = false)
    private boolean soft;

    /** The most OPEN or PENDING claims each person may have in the period; null for no cap. */
    @Column(name = "claim_cap")
    private Integer cap;

    /** The due-total fixed when the period was closed; null while it is open. */
    @Column(name = "closed_total", precision = 12, scale = 2)
    private BigDecimal closedTotal;

    /** Each person's due-total for the period fixed when it was closed, by person id; empty while it
     * is open. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_total", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "total", precision = 12, scale = 2, nullable = false)
    private Map<Long, BigDecimal> closedPersonTotals = new HashMap<>();

    protected Period() {
    }

    public Period(String sheetId, String name, LocalDate from, LocalDate to) {
        this.sheetId = sheetId;
        this.name = name.trim();
        this.nameKey = keyOf(name);
        this.from = from;
        this.to = to;
    }

    public Period(String sheetId, String name, LocalDate from, LocalDate to, Integer cap) {
        this(sheetId, name, from, to);
        this.cap = cap;
    }

    /** The name as compared: without the spaces around it, in lower case. */
    public static String keyOf(String name) {
        return name.trim().toLowerCase(Locale.ROOT);
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public LocalDate getFrom() {
        return from;
    }

    public LocalDate getTo() {
        return to;
    }

    public Integer getCap() {
        return cap;
    }

    public boolean isClosed() {
        return closed;
    }

    public boolean isSoft() {
        return soft;
    }

    public BigDecimal getClosedTotal() {
        return closedTotal;
    }

    public Map<Long, BigDecimal> getClosedPersonTotals() {
        return Map.copyOf(closedPersonTotals);
    }

    /** Close the period, fixing each person's due-total for it at {@code personTotals}, by person id,
     * and its own due-total at their sum. */
    public void close(Map<Long, BigDecimal> personTotals) {
        close(personTotals, false);
    }

    /** Close the period as {@link #close(Map)} does, soft-closed when {@code soft}. */
    public void close(Map<Long, BigDecimal> personTotals, boolean soft) {
        this.closed = true;
        this.soft = soft;
        this.closedPersonTotals.clear();
        this.closedPersonTotals.putAll(personTotals);
        this.closedTotal = personTotals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /** Forget the due-total fixed for the person {@code personId}, who leaves the sheet. The period's own
     * due-total is unchanged. */
    public void dropPersonTotal(Long personId) {
        closedPersonTotals.remove(personId);
    }

    /** Fold the due-total fixed for the person {@code from} into the one fixed for {@code into}: the
     * person {@code from} is merged into {@code into}. The period's own due-total is unchanged. */
    public void mergePersonTotal(Long from, Long into) {
        BigDecimal moved = closedPersonTotals.remove(from);
        if (moved != null) closedPersonTotals.merge(into, moved, BigDecimal::add);
    }

    /** Reopen the period: its due-total is live again. */
    public void reopen() {
        this.closed = false;
        this.soft = false;
        this.closedTotal = null;
        this.closedPersonTotals.clear();
    }

    /** Whether this period shares a day with the dates {@code from} to {@code to}, both inclusive. */
    public boolean overlaps(LocalDate from, LocalDate to) {
        return !this.from.isAfter(to) && !from.isAfter(this.to);
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.TreeSet;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonTree;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * A sheet's descendants (its children — the sheets naming it as their parent — their children, and so
 * on) and their figures added up: the number of people on them (retired ones included) and each one's
 * due-total and overdue-total as that sheet shows it. The screen adds the sheet's own figures to give
 * the consolidated figures.
 */
@Service
public class ConsolidatedService {

    /** The descendants' figures added up, with two decimals; all zero when the sheet has no children. */
    public record Figures(int peopleCount, String dueTotal, String overdueTotal) {
    }

    private final SheetRepository sheets;
    private final RollupService rollup;
    private final PersonTree tree;
    private final PersonRepository people;

    public ConsolidatedService(SheetRepository sheets, RollupService rollup, PersonTree tree,
            PersonRepository people) {
        this.sheets = sheets;
        this.rollup = rollup;
        this.tree = tree;
        this.people = people;
    }

    /** One person found by {@link #search}: their sheet, name and due-total as that sheet shows it. */
    public record Found(String sheet, String name, String dueTotal) {
    }

    /** Every person of the sheet and the other sheets of its tree whose name or an alias contains
     * {@code text} (case ignored; blank finds everyone): the sheet's own people first in list order, then
     * the other sheets' by sheet id, each sheet's in its list order. */
    @Transactional(readOnly = true)
    public List<Found> search(String sheetId, String text) {
        String needle = text == null ? "" : text.trim().toLowerCase(Locale.ROOT);
        List<String> order = new ArrayList<>();
        order.add(sheetId);
        order.addAll(new TreeSet<>(tree.othersOf(sheetId)));
        List<Found> found = new ArrayList<>();
        for (String id : order) {
            RollupService.Snapshot snapshot = rollup.snapshot(id);
            for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(id)) {
                if (!matches(person.getName(), needle)
                        && person.getAliases().stream().noneMatch(a -> matches(a, needle))) continue;
                RollupService.Figures figures = snapshot.people().get(person.getId());
                found.add(new Found(id, person.getName(),
                        figures == null ? RollupService.NONE : figures.dueTotal()));
            }
        }
        return found;
    }

    private static boolean matches(String value, String needle) {
        return value != null && value.toLowerCase(Locale.ROOT).contains(needle);
    }

    /** The figures of the sheet itself and its descendants as they stand, added up: the consolidated
     * figures the screen shows while it reads the sheet as it stood on an earlier date. */
    @Transactional(readOnly = true)
    public Figures consolidatedOf(String sheetId) {
        Figures descendants = descendantsOf(sheetId);
        RollupService.Snapshot own = rollup.snapshot(sheetId);
        return new Figures(descendants.peopleCount() + own.people().size(),
                new BigDecimal(descendants.dueTotal()).add(new BigDecimal(own.dueTotal())).toPlainString(),
                new BigDecimal(descendants.overdueTotal()).add(new BigDecimal(own.overdueTotal())).toPlainString());
    }

    /** The figures of the sheet's descendants as they stand, added up. */
    @Transactional(readOnly = true)
    public Figures descendantsOf(String sheetId) {
        Set<String> seen = new HashSet<>();
        seen.add(sheetId);
        Deque<String> parents = new ArrayDeque<>();
        parents.add(sheetId);
        int count = 0;
        BigDecimal due = BigDecimal.ZERO.setScale(2);
        BigDecimal overdue = BigDecimal.ZERO.setScale(2);
        while (!parents.isEmpty()) {
            for (Sheet child : sheets.findByParentIdOrderByIdAsc(parents.poll())) {
                if (!seen.add(child.getId())) continue;
                parents.add(child.getId());
                RollupService.Snapshot snapshot = rollup.snapshot(child.getId());
                count += snapshot.people().size();
                due = due.add(new BigDecimal(snapshot.dueTotal()));
                overdue = overdue.add(new BigDecimal(snapshot.overdueTotal()));
            }
        }
        return new Figures(count, due.toPlainString(), overdue.toPlainString());
    }
}

