-- Each person's due-total for a closed period, fixed when it was closed: what is due on their
-- counting claims dated in it. A person with no row here shows 0.00 for the closed period. The
-- rows are removed when the period is reopened.
CREATE TABLE period_person_total (
    period_id BIGINT         NOT NULL REFERENCES period (id),
    person_id BIGINT         NOT NULL REFERENCES person (id),
    total     DECIMAL(12, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** The periods of a sheet. The signed-in user's name travels in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/periods")
@Validated
public class PeriodController {

    /** A period, with whether it is closed, whether that is only a soft close, and the due-total fixed when it was closed (null while it is
     * open) and each person's due-total for it fixed then, by person id (empty while it is open), sent
     * as text with two decimals so they are never rounded on the way. */
    public record PeriodView(long id, String name, LocalDate from, LocalDate to, Integer cap, boolean closed,
            boolean soft, String closedTotal, Map<Long, String> closedPersonTotals) {
        static PeriodView of(Period period) {
            Map<Long, String> personTotals = new TreeMap<>();
            period.getClosedPersonTotals().forEach((id, total) -> personTotals.put(id, text(total)));
            return new PeriodView(period.getId(), period.getName(), period.getFrom(), period.getTo(), period.getCap(),
                    period.isClosed(), period.isSoft(), period.getClosedTotal() == null ? null : text(period.getClosedTotal()),
                    personTotals);
        }

        private static String text(BigDecimal amount) {
            return amount.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
        }
    }

    /** A period's name (not blank, no spaces inside, kept without the spaces around it) and its from
     * and to dates, both inclusive, and the most OPEN or PENDING claims each person may have in it: a
     * whole number of at least one, blank or missing for no cap. */
    public record PeriodRequest(
            @NotBlank @Size(max = 100) @Pattern(regexp = "\\s*\\S+\\s*") String name,
            @NotNull LocalDate from,
            @NotNull LocalDate to,
            @Pattern(regexp = "\\s*(\\d{1,9})?\\s*") String cap) {
        Integer capValue() {
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

export interface Period {
  id: number;
  name: string;
  /** The first day of the period (YYYY-MM-DD). */
  from: string;
  /** The last day of the period (YYYY-MM-DD). */
  to: string;
  /** The most OPEN or PENDING claims each person may have in the period; null for no cap. */
  cap: number | null;
  /** Whether the period is closed: no claim dated in it can change. */
  closed: boolean;
  /** Whether the closed period is only soft-closed: its figures are fixed, but claims dated in it can
   *  still change. */
  soft: boolean;
  /** The due-total fixed when the period was closed, with two decimals; null while it is open. */
  closedTotal: string | null;
  /** Each person's due-total for the period fixed when it was closed, with two decimals, by person
   *  id; empty while it is open. A person not in it (added later) has 0.00 for the closed period. */
  closedPersonTotals: Record<string, string>;
}

export interface PeriodFields {
  name: string;
  from: string;
  to: string;
  /** The cap on each person's OPEN or PENDING claims in the period: a whole number, blank for none. */
  cap: string;
}

